from fractions import gcd
import fractions

def ok(a, b, c):
	if c >= a and c >= b:
		return False
	else:
		gcd = fractions.gcd(a, b)
		if c % gcd == 0:
			return True
		else:
			return False
sa = int(input())
for t in range(sa):
	sa2 = input().split(' ')
	if ok(int(sa2[0]), int(sa2[1]), int(sa2[2])):
		print('YES')
	else:
		print('NO')
